  "routes": [
    [
      "GET",
      "/v1\\.0/me"
    ],
    [
      "GET",
      "/v1\\.0/me/messages"
    ],
    [
      "GET",
      "/v1\\.0/me/messages/[A-Za-z0-9%_=+-]{1,400}"
    ],
    [
      "GET",
      "/v1\\.0/me/mailFolders/inbox"
    ]
